      stress: {
        O: {high:{t:'Equilíbrio no novo', k:'Pessoas abertas recuperam muitas vezes com estímulos: um livro, música, um lugar novo, algo criativo. Ficar sem fazer nada descansa-as menos.', d:'Em alturas de stress, oferece-te algo estimulante que nada tenha a ver com o trabalho.', f:'O que te tirou completamente da cabeça os problemas da última vez?'}, low:{t:'Descanso no habitual', k:'Quem procura menos novidade recupera melhor em rotinas conhecidas: caminhos sabidos, lugares favoritos, hábitos fixos.', d:'Em alturas exigentes, o conhecido ajuda-te mais do que o novo. Protege as tuas rotinas precisamente então.', f:'Que hábito te dá calma de forma fiável?'}},
        C: {high:{t:'Um plano contra a pressão', k:'Pessoas conscienciosas reduzem o stress planeando, e planear baixa mesmo a pressão. Mas o que fica por fazer pode ocupá-las mais tempo.', d:'À noite, escreve o que te espera amanhã. Assim a cabeça pode largar sem que nada se perca.', f:'O que levas agora na cabeça que estaria melhor no papel?'}, low:{t:'Stress do atraso', k:'Pessoas menos conscienciosas raramente se stressam por exigência, mais quando o que está pendente se acumula.', d:'Um pequeno sistema ajuda-te mais do que a boa vontade: uma lista, um momento fixo por dia para a ver.', f:'O que está parado há semanas e levaria dez minutos?'}},
        E: {high:{t:'Recarregar com outros', k:'Pessoas extrovertidas recuperam em companhia. Demasiado tempo sozinhas, o humor tende a baixar.', d:'Quando aperta, planeia tempo com pessoas que te fazem bem. Não é distração, é recuperação.', f:'A quem poderias simplesmente ligar esta semana?'}, low:{t:'Recarregar a sós', k:'Pessoas mais reservadas recuperam no sossego. Muitos estímulos e encontros custam-lhes energia, mesmo agradáveis.', d:'Depois de dias cheios, reserva de propósito tempo para ti. É cuidado, não retirada.', f:'De quanto tempo a sós precisas mesmo depois de um dia cheio?'}},
        A: {high:{t:'Os conflitos chegam perto', k:'Pessoas amáveis levam muitas vezes para casa as tensões com outros e dizem sim mais vezes do que lhes faz bem.', d:'Um não simpático protege a tua energia e as tuas relações. Podes pedir tempo para pensar antes de aceitar.', f:'A que pedido terias preferido dizer não recentemente?'}, low:{t:'Menos vulnerável', k:'Pessoas menos amáveis ficam menos sobrecarregadas com conflitos. Aceitar ajuda pode, em contrapartida, custar-lhes mais.', d:'Aceitar apoio não é fraqueza. Quem te ajuda sente-se muitas vezes mais próximo de ti depois.', f:'Em que te ajudaria alguém de bom grado agora, se pedisses?'}},
        S: {high:{t:'Depressa de novo em equilíbrio', k:'Pessoas emocionalmente estáveis recuperam depressa da carga. Isso protege, mas pode levar a ignorar sinais do próprio cansaço.', d:'A tua resiliência é grande. Ainda assim, cuida do sono e das pausas antes que o corpo as exija.', f:'Como perceberias que, afinal, é demasiado?'}, low:{t:'Mais tocado', k:'Quem reage com mais força à carga tende a ruminar e sente a pressão no corpo. Dormir, mexer-se e nomear os sentimentos ajudam comprovadamente.', d:'Coisas pequenas e regulares resultam melhor contigo do que grandes resoluções: um passeio, horários fixos de sono, uma frase num diário.', f:'O que te acalma de forma fiável, e quando o fizeste pela última vez?'}},
      },
      wachstum: {
        O: {high:{t:'Ousar a profundidade', k:'Pessoas abertas gostam de começar coisas novas. Crescer, para elas, passa muitas vezes por ficar com uma coisa até a dominar a sério.', d:'Escolhe um tema e segue-o durante um ano. A profundidade pode surpreender-te mais do que qualquer ideia nova.', f:'Que interesse começado merece uma segunda volta, mais longa?'}, low:{t:'Abrir uma janela', k:'Quem procura menos novidade cresce muitas vezes com pequenas incursões dirigidas ao desconhecido, ligadas a algo conhecido.', d:'Uma vez por mês, experimenta algo novo que se ligue a algo de que já gostas.', f:'Qual seria um pequeno passo fora dos teus caminhos habituais?'}},
        C: {high:{t:'Praticar largar', k:'Pessoas conscienciosas crescem muitas vezes quando cedem o controlo: partilhar tarefas, tolerar o inacabado, pausas sem objetivo.', d:'Planeia de propósito algo sem plano. Uma tarde livre é, para ti, treino e não desperdício.', f:'O que poderias deixar a outra pessoa esta semana?'}, low:{t:'Pequenos hábitos', k:'A conscienciosidade não é fixa: na maioria das pessoas cresce ao longo da vida. Pequenos hábitos fixos são o caminho mais fiável.', d:'Começa com um hábito de menos de dois minutos e prende-o a algo que já fazes.', f:'Que hábito de dois minutos te tornaria o dia mais fácil?'}},
        E: {high:{t:'O silêncio como espaço', k:'Pessoas extrovertidas crescem muitas vezes a ouvir e a estar sozinhas, em momentos em que não são elas a levar o grupo.', d:'Deixa de propósito uma pausa numa conversa. O mais importante da outra pessoa vem muitas vezes logo a seguir.', f:'Quem ouviste pela última vez sem pensar na tua resposta?'}, low:{t:'Sair em doses', k:'Pessoas mais reservadas crescem com encontros ao seu ritmo: grupos pequenos, conversas a dois, temas que realmente lhes interessam.', d:'Procura contactos através de interesses comuns. Aí a conversa vem por si.', f:'Que encontro te deu recentemente mais do que te custou?'}},
        A: {high:{t:'Limites como gentileza', k:'Pessoas amáveis crescem quando levam as próprias necessidades tão a sério como as dos outros. Limites claros não arrefecem as relações, tornam-nas mais sinceras.', d:'Pratica frases como “Isso não me dá jeito, mas…”. São gentis e claras ao mesmo tempo.', f:'Que limite gostarias de expressar uma vez?'}, low:{t:'Mostrar calor', k:'Pessoas menos amáveis crescem muitas vezes quando expressam o apreço que já sentem mas raramente dizem.', d:'Esta semana, diz a alguém, em concreto, o que aprecias nessa pessoa. Custa pouco e fica muito tempo.', f:'Quem merece um elogio que até agora só pensaste?'}},
        S: {high:{t:'Compreensão pelos outros', k:'Pessoas emocionalmente estáveis crescem na compaixão por quem é mais facilmente tocado, em vez de o medir pela própria bitola.', d:'Pergunta antes de tranquilizar. “De que precisas agora?” ajuda muitas vezes mais do que “Vai correr bem”.', f:'Quem tranquilizaste da última vez quando, na verdade, queria ser ouvido?'}, low:{t:'Gentil contigo', k:'Na maioria das pessoas, a estabilidade emocional aumenta com os anos. A autocompaixão, falar contigo como com alguém de quem gostas, ajuda comprovadamente.', d:'Nos dias difíceis, fala contigo como falarias com alguém de quem gostas.', f:'O que dirias a alguém que se sente agora como tu?'}},
      },
